onRequestGet: PagesFunction<Env> = async (context) => {
  const { env } = context;

  let entries: LeaderboardEntry[] = [];
  try {
    const raw = await env.KAOS_STATS.get('leaderboard');
    if (raw) {
      entries = JSON.parse(raw) as LeaderboardEntry[];
    }
  } catch {
    // KV read or parse failed — return empty so the frontend can
    // fall back to client-side fetchRecentLeaderboard().
    entries = [];
  }

  return new Response(JSON.stringify(entries), {
    status: 200,
    headers: {
      'Content-Type': 'application/json',
      'Cache-Control': 'public, max-age=60',
    },
  });
}

