async function index(env: Env): Promise<void> {
  const rpcUrl = env.KAOS_RPC ?? DEFAULT_RPC;
  const tokenAddr = (env.KAOS_TOKEN ?? KAOS_TOKEN_ADDR) as Address;
  const deployBlock = env.DEPLOY_BLOCK
    ? BigInt(env.DEPLOY_BLOCK)
    : DEFAULT_DEPLOY_BLOCK;

  const client = createPublicClient({
    chain: base,
    transport: http(rpcUrl),
  });

  // Determine the scan window: (lastBlock, currentBlock].
  const currentBlock = await client.getBlockNumber();

  const lastBlockRaw = await env.KAOS_STATS.get('lastBlock');
  const lastBlock = lastBlockRaw ? BigInt(lastBlockRaw) : 0n;
  const fromBlock = lastBlock === 0n ? deployBlock : lastBlock + 1n;

  // Nothing to scan (current block hasn't advanced).
  if (fromBlock > currentBlock) return;

  // Fetch trigger logs across all 21 event signatures.
  const eventNames = TRIGGERS.map((t) => t.name);
  const logs: Log[] = [];
  for (const name of eventNames) {
    try {
      // Cast name — getAbiItem expects a literal union, but the ABI
      // contains all 21 trigger event names so this is safe.
      const abiItem = getAbiItem({ abi: kaosTokenAbi, name: name as any });
      const result = await client.getLogs({
        address: tokenAddr,
        event: abiItem as any,
        fromBlock,
        toBlock: currentBlock,
      });
      logs.push(...result);
    } catch {
