function parseTriggerLog(log: Log): TriggerEvent | null {
  if (!log.topics[0]) return null;

  try {
    const decoded = decodeEventLog({
      abi: kaosTokenAbi,
      data: log.data,
      topics: log.topics,
    });

    const triggerName = decoded.eventName;
    const trigger = TRIGGERS.find((t) => t.name === triggerName) ?? null;
    const args = decoded.args as Record<string, unknown>;

    const player = (args.player as string) ?? '0x0';
    const amount = (args.amount as bigint) ?? (args.playerAmount as bigint) ?? 0n;
    const burnAmount = (args.burnAmount as bigint) ?? 0n;
    const houseAmount = (args.houseAmount as bigint) ?? 0n;

    return {
      triggerName,
      trigger,
      player,
      amount,
      burnAmount,
      houseAmount,
      blockNumber: log.blockNumber,
      txHash: log.transactionHash ?? '0x0',
      logIndex: log.logIndex,
      isBurn: trigger?.type === 'burn',
      isHouse: trigger?.type === 'house' || trigger?.type === 'mixed',
      isNothing: trigger?.type === 'nothing',
    };
  } catch {
    return null;
  }
}

