async function fetchRecentLeaderboard(
  blockRange: bigint = 100_000n,
): Promise<LeaderboardEntry[]> {
  const events = await fetchRecentTriggers(blockRange);

  const byPlayer = new Map<string, LeaderboardEntry>();

  for (const ev of events) {
    if (ev.isNothing || ev.isBurn) continue;
    const existing = byPlayer.get(ev.player);
    if (existing) {
      existing.totalWon += ev.amount;
      existing.triggerCount += 1;
      if (ev.amount > existing.bestAmount) {
        existing.bestAmount = ev.amount;
        existing.bestTrigger = ev.triggerName;
      }
    } else {
      byPlayer.set(ev.player, {
        player: ev.player,
        totalWon: ev.amount,
        triggerCount: 1,
        bestTrigger: ev.triggerName,
        bestAmount: ev.amount,
      });
    }
  }

  return Array.from(byPlayer.values())
    .sort((a, b) => Number(b.totalWon - a.totalWon))
    .slice(0, 100);
}

